-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several holds over time. Only a person's OPEN claims dated within one of their holds, and
-- not bound by a statement, are left out of the live totals. A person on hold before holds were
-- dated keeps a hold from the beginning of time with no end.
CREATE TABLE person_hold (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_sheet ON person_hold (sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date)
    SELECT sheet_id, id, DATE '0001-01-01', NULL FROM person WHERE held = TRUE;
ALTER TABLE person DROP COLUMN held;
-- A person who is unretired keeps the retirement they had: from the date they were retired from to
-- the sheet's today when they were unretired. A person may have several over time.
CREATE TABLE person_retirement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
CREATE INDEX person_retirement_sheet ON person_retirement (sheet_id, person_id);
-- A sheet's retired grades: a retired grade cannot be chosen for a person any more (the people on it
-- keep it). A grade is retired on a sheet at most once.
CREATE TABLE retired_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL
);
CREATE UNIQUE INDEX retired_grade_sheet_grade ON retired_grade (sheet_id, grade);
-- A person's grade is dated: each grade a person is given applies from its from-date, and the one in
-- force on a date is the one whose from-date is the latest on or before it. The first grade a person
-- was given has no from-date and applies from the beginning of time. A person has at most one grade
-- per from-date (no from-date counting as one).
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade CHAR(1) NOT NULL,
    from_date DATE,
    from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;

